//! The agent fixtures (`agent-modes`, `agent-registry`, `agent-queue`, `fixall-claim`) against the
//! Rust side (AWTD-1550).
//!
//! They were generated by astrid-web's exporter (AWTD-1566) and copied here with no reader, so
//! nothing checked that core's agent rows, or anything decoding the queue and claim answers, says
//! what the web route says. These read every case.

use astrid_rules::agent_protocol::{AgentQueue, ClaimOutcome, RunnableReason};
use astrid_rules::rows::agent::{label_for, rows, settable_modes, AgentMode};
use serde_json::{json, Value};

const MODES: &str = include_str!("../../../contracts/fixtures/agent-modes.json");
const REGISTRY: &str = include_str!("../../../contracts/fixtures/agent-registry.json");
const QUEUE: &str = include_str!("../../../contracts/fixtures/agent-queue.json");
const CLAIM: &str = include_str!("../../../contracts/fixtures/fixall-claim.json");

fn parse(text: &str) -> Value {
    serde_json::from_str(text).expect("the fixture parses")
}

#[test]
fn agent_rows_project_every_agent_the_route_lists_awtd_1550() {
    let answer = parse(MODES);
    let projected = rows(&answer);
    let listed = answer["agents"].as_array().unwrap();
    assert_eq!(projected.len(), listed.len());
    for (row, agent) in projected.iter().zip(listed) {
        assert_eq!(row.id, agent["mailbox"].as_str().unwrap());
        assert_eq!(row.email.as_deref(), agent["email"].as_str());
        let mode: AgentMode = serde_json::from_value(agent["mode"].clone()).unwrap();
        assert_eq!(row.mode, mode, "{}", row.id);
        assert_eq!(row.locked, agent["locked"].as_bool().unwrap(), "{}", row.id);
        assert_eq!(row.modes, settable_modes(row.locked).to_vec(), "{}", row.id);
    }
}

#[test]
fn the_locked_agents_are_the_registrys_polling_only_ones_awtd_1550() {
    let registry = parse(REGISTRY);
    let polling_only: Vec<&str> = registry["pollingOnly"]
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_str().unwrap())
        .collect();
    for row in rows(&parse(MODES)) {
        assert_eq!(
            row.locked,
            polling_only.contains(&row.id.as_str()),
            "{}",
            row.id
        );
        if row.locked {
            // A polling-only agent can poll or be unused, nothing else.
            assert_eq!(row.modes, vec![AgentMode::Polling, AgentMode::Off]);
        }
    }
}

#[test]
fn core_names_harness_agents_as_the_registry_does_awtd_1550() {
    for agent in parse(REGISTRY)["harnessAgents"].as_array().unwrap() {
        let mailbox = agent["mailbox"].as_str().unwrap();
        assert_eq!(
            label_for(mailbox),
            agent["label"].as_str().unwrap(),
            "{mailbox}"
        );
    }
}

#[test]
fn a_mailbox_the_server_learns_later_still_projects_awtd_1550() {
    let mut answer = parse(MODES);
    answer["agents"]
        .as_array_mut()
        .unwrap()
        .push(json!({ "mailbox": "zephyr", "email": "zephyr@astrid.cc", "mode": "polling", "locked": false }));
    let row = rows(&answer)
        .into_iter()
        .find(|row| row.id == "zephyr")
        .expect("projected");
    assert_eq!(row.name, "Zephyr");
    assert_eq!(row.mode, AgentMode::Polling);
}

#[test]
fn extra_fields_are_tolerated_awtd_1550() {
    let plain = rows(&parse(MODES));
    let mut answer = parse(MODES);
    answer["futureField"] = json!({ "anything": true });
    for agent in answer["agents"].as_array_mut().unwrap() {
        agent["capabilities"] = json!(["new"]);
    }
    assert_eq!(rows(&answer), plain);

    let mut queue = parse(QUEUE)["scenarios"]["available"].clone();
    queue["futureField"] = json!(1);
    queue["queue"][0]["estimate"] = json!("2h");
    queue["runnable"]["confidence"] = json!(0.9);
    let decoded: AgentQueue =
        serde_json::from_value(queue).expect("extra fields do not break the decode");
    assert_eq!(decoded.queue.len(), 1);
}

#[test]
fn every_queue_scenario_decodes_into_the_typed_answer_awtd_1550() {
    let fixture = parse(QUEUE);
    for (name, scenario) in fixture["scenarios"].as_object().unwrap() {
        let queue: AgentQueue = serde_json::from_value(scenario.clone())
            .unwrap_or_else(|error| panic!("{name}: {error}"));
        assert_eq!(
            queue.agent.mailbox,
            scenario["agent"]["mailbox"].as_str().unwrap(),
            "{name}"
        );
        assert_eq!(queue.empty, scenario["empty"].as_bool().unwrap(), "{name}");
        assert_eq!(
            queue.queue.len(),
            scenario["queue"].as_array().unwrap().len(),
            "{name}"
        );
        assert_eq!(queue.hint.as_deref(), scenario["hint"].as_str(), "{name}");
        assert_eq!(
            queue.held.not_due_count,
            scenario["held"]["notDueCount"].as_u64().unwrap(),
            "{name}"
        );
        assert_eq!(
            queue.attention.tasks.len(),
            scenario["attention"]["tasks"].as_array().unwrap().len(),
            "{name}"
        );
        let runnable = queue.runnable.expect("this server sends runnable");
        assert_eq!(
            runnable.has_work,
            scenario["runnable"]["hasWork"].as_bool().unwrap(),
            "{name}"
        );
        assert_eq!(
            runnable.incomplete,
            scenario["runnable"]["incomplete"].as_bool().unwrap(),
            "{name}"
        );
    }
    let available: AgentQueue =
        serde_json::from_value(fixture["scenarios"]["available"].clone()).unwrap();
    assert_eq!(
        available.runnable.unwrap().reasons,
        vec![RunnableReason::Ready, RunnableReason::Attention]
    );
}

#[test]
fn an_older_server_without_runnable_still_decodes_awtd_1550() {
    let mut scenario = parse(QUEUE)["scenarios"]["available"].clone();
    scenario.as_object_mut().unwrap().remove("runnable");
    let queue: AgentQueue = serde_json::from_value(scenario).unwrap();
    assert!(queue.runnable.is_none());
}

#[test]
fn claim_outcomes_read_as_the_route_answers_them_awtd_1550() {
    let outcomes = parse(CLAIM);
    let read = |key: &str| {
        let case = &outcomes["outcomes"][key];
        ClaimOutcome::from_response(case["status"].as_u64().unwrap() as u16, &case["body"])
    };
    assert_eq!(
        read("claimed"),
        ClaimOutcome::Claimed {
            task_id: "task-claim-fixture".into(),
            agent: Some("claude".into())
        }
    );
    assert!(matches!(read("conflict"), ClaimOutcome::Conflict { .. }));
    assert!(matches!(read("notReady"), ClaimOutcome::Conflict { .. }));
    assert!(matches!(read("forbidden"), ClaimOutcome::Forbidden { .. }));
}
